public sealed class DocumentaryProductionAdaptersOptionsValidator : IValidateOptions<DocumentaryProductionAdaptersOptions> { public ValidateOptionsResult Validate(string? name,DocumentaryProductionAdaptersOptions o){var errors=new List<string>();if(o.CleanupTimeoutSeconds is <1 or >3600)errors.Add("CleanupTimeoutSeconds must be between 1 and 3600.");if(o.DefaultOperationTimeoutSeconds is <1 or >86400)errors.Add("DefaultOperationTimeoutSeconds must be between 1 and 86400.");if(o.ExecutionMode==DocumentaryProductionExecutionMode.Certified&&!o.Enabled)errors.Add("Certified mode requires Enabled.");if(o.Enabled&&string.IsNullOrWhiteSpace(o.WorkspaceRoot))errors.Add("WorkspaceRoot is required when enabled.");if(!string.IsNullOrWhiteSpace(o.WorkspaceRoot)){try{_ = Path.GetFullPath(o.WorkspaceRoot);}catch(Exception e) when(e is ArgumentException or NotSupportedException or PathTooLongException){errors.Add("WorkspaceRoot is not a legal path.");}}return errors.Count==0?ValidateOptionsResult.Success:ValidateOptionsResult.Fail(errors);} }
public sealed class DocumentaryProductionExecutionHostOptionsValidator : IValidateOptions<DocumentaryProductionExecutionHostOptions> { public ValidateOptionsResult Validate(string? name,DocumentaryProductionExecutionHostOptions o){var errors=new List<string>();if(o.MaximumAttemptsPerOperation is <1 or >10)errors.Add("MaximumAttemptsPerOperation must be between 1 and 10.");foreach(var value in new[]{o.VisualGenerationTimeoutSeconds,o.NarrationSynthesisTimeoutSeconds,o.SubtitleGenerationTimeoutSeconds,o.SceneCompositionTimeoutSeconds,o.VariantCompositionTimeoutSeconds,o.MediaVerificationTimeoutSeconds})if(value is <1 or >86400)errors.Add("Operation timeouts must be between 1 and 86400 seconds.");return errors.Count==0?ValidateOptionsResult.Success:ValidateOptionsResult.Fail(errors);} }
public sealed class DocumentaryRealProviderSmokeOptionsValidator : IValidateOptions<DocumentaryRealProviderSmokeOptions> { public ValidateOptionsResult Validate(string? name,DocumentaryRealProviderSmokeOptions o){var errors=new List<string>();if(o.MaximumExecutionMinutes is <1 or >60)errors.Add("MaximumExecutionMinutes must be between 1 and 60.");if(o.MinimumFreeDiskBytes<1)errors.Add("MinimumFreeDiskBytes must be positive.");if(o.Enabled&&string.IsNullOrWhiteSpace(o.WorkspaceRoot))errors.Add("A dedicated smoke WorkspaceRoot is required when enabled.");if(!o.Enabled&&(o.RunAzureSpeech||o.RunVisualProvider||o.RunSceneComposition||o.RunVariantComposition||o.RunMediaVerification))errors.Add("Provider smoke switches require RealProviderSmoke.Enabled.");return errors.Count==0?ValidateOptionsResult.Success:ValidateOptionsResult.Fail(errors);} }
public sealed class DocumentaryProductionFailureNormalizer : IDocumentaryProductionFailureNormalizer { public DocumentaryProductionFailure Normalize(Exception e,DocumentaryProductionOperationKind operation,bool callerCancelled){if(e is OperationCanceledException&&callerCancelled)throw e;var code=e switch{OperationCanceledException when operation is DocumentaryProductionOperationKind.SceneComposition or DocumentaryProductionOperationKind.VariantComposition=>DocumentaryProductionFailureCode.ProcessTimedOut,OperationCanceledException or TimeoutException=>DocumentaryProductionFailureCode.ProviderTimeout,FileNotFoundException=>DocumentaryProductionFailureCode.SourceArtifactMissing,DirectoryNotFoundException=>DocumentaryProductionFailureCode.SourceArtifactMissing,UnauthorizedAccessException or IOException=>DocumentaryProductionFailureCode.FileSystemFailure,ArgumentException or InvalidOperationException=>DocumentaryProductionFailureCode.ProviderRejectedRequest,_=>DocumentaryProductionFailureCode.ProviderUnavailable};return new(code,code switch{DocumentaryProductionFailureCode.SourceArtifactMissing=>"A required source artifact is missing.",DocumentaryProductionFailureCode.FileSystemFailure=>"A filesystem operation failed.",DocumentaryProductionFailureCode.ProviderTimeout=>"The provider operation timed out.",DocumentaryProductionFailureCode.ProcessTimedOut=>"The process timed out.",_=>"The production operation failed."},code is DocumentaryProductionFailureCode.ProviderTimeout or DocumentaryProductionFailureCode.ProcessTimedOut);}}
public sealed class EmptyDocumentaryProductionAdapterRegistry : IDocumentaryProductionAdapterRegistry { public IDocumentaryProductionVisualAdapter? VisualGeneration=>null; public IDocumentaryProductionNarrationAdapter? NarrationSynthesis=>null; public IDocumentaryProductionSubtitleAdapter? SubtitleGeneration=>null; public IDocumentaryProductionSceneCompositionAdapter? SceneComposition=>null; public IDocumentaryProductionVariantCompositionAdapter? VariantComposition=>null; public IDocumentaryProductionMediaVerificationAdapter? MediaVerification=>null; public bool IsAvailable(DocumentaryProductionOperationKind operation)=>false; }
public sealed class DocumentaryProductionExecutionRecordMapper : IDocumentaryProductionExecutionRecordMapper { public DocumentaryMediaAssetResult MapAsset(DocumentaryArtifactMappingContext c){var p=c.Plan;var d=c.Descriptor;if(p.AssetId!=d.AssetId||p.CorrelationId!=d.CorrelationId)throw new ArgumentException("Mapping identity mismatch.");return new(d.AssetId,p.AssetType,p.AssetFormat,DocumentaryMediaAssetStatus.Generated,d.ProviderId,d.ContentIdentity,d.Length,d.DurationMilliseconds??0,d.Width??0,d.Height??0,(int)(d.FrameRate??0),d.AudioSampleRate??0,d.AudioChannelCount??0,d.Checksum,null,null,d.AttemptCount,d.CorrelationId);} }
public static class DocumentaryProductionBridgeServiceCollectionExtensions { public static IServiceCollection AddDocumentaryProductionBridge(this IServiceCollection services,IConfiguration configuration){services.AddOptions<DocumentaryProductionAdaptersOptions>().Bind(configuration.GetSection(DocumentaryProductionAdaptersOptions.SectionName));services.AddOptions<DocumentaryRealProviderSmokeOptions>().Bind(configuration.GetSection(DocumentaryRealProviderSmokeOptions.SectionName));services.AddOptions<DocumentaryProductionExecutionHostOptions>().Bind(configuration.GetSection(DocumentaryProductionExecutionHostOptions.SectionName));services.AddOptions<DocumentaryVisualAdapterOptions>().Bind(configuration.GetSection(DocumentaryVisualAdapterOptions.SectionName));services.AddOptions<DocumentaryNarrationAdapterOptions>().Bind(configuration.GetSection(DocumentaryNarrationAdapterOptions.SectionName));services.AddOptions<DocumentarySubtitleAdapterOptions>().Bind(configuration.GetSection(DocumentarySubtitleAdapterOptions.SectionName));services.AddOptions<DocumentarySceneCompositionAdapterOptions>().Bind(configuration.GetSection(DocumentarySceneCompositionAdapterOptions.SectionName));services.AddOptions<DocumentaryVariantCompositionAdapterOptions>().Bind(configuration.GetSection(DocumentaryVariantCompositionAdapterOptions.SectionName));services.AddOptions<DocumentaryMediaVerificationAdapterOptions>().Bind(configuration.GetSection(DocumentaryMediaVerificationAdapterOptions.SectionName));services.AddOptions<RenderingOptions>().Bind(configuration.GetSection(RenderingOptions.SectionName));services.AddSingleton<IValidateOptions<DocumentaryProductionAdaptersOptions>,DocumentaryProductionAdaptersOptionsValidator>();services.AddSingleton<IValidateOptions<DocumentaryRealProviderSmokeOptions>,DocumentaryRealProviderSmokeOptionsValidator>();services.AddSingleton<IValidateOptions<DocumentaryProductionExecutionHostOptions>,DocumentaryProductionExecutionHostOptionsValidator>();services.AddSingleton<IDocumentaryProductionClock,SystemDocumentaryProductionClock>();services.AddSingleton<IDocumentaryExecutionIdGenerator,DocumentaryExecutionIdGenerator>();services.AddSingleton<IDocumentarySafeFileNameGenerator,DocumentarySafeFileNameGenerator>();services.AddSingleton<IDocumentaryChecksumService,DocumentaryChecksumService>();services.AddSingleton<IDocumentaryContentIdentityFactory,DocumentaryContentIdentityFactory>();services.AddSingleton<IDocumentaryPhysicalArtifactDescriptorValidator,DocumentaryPhysicalArtifactDescriptorValidator>();services.AddSingleton<IDocumentaryFfprobeResultParser,DocumentaryFfprobeResultParser>();services.TryAddScoped<ExistingFfprobeDocumentaryMediaProbe>();services.TryAddScoped<IDocumentaryFfprobeProbe>(sp=>sp.GetRequiredService<ExistingFfprobeDocumentaryMediaProbe>());services.TryAddScoped<IDocumentaryMediaProbe>(sp=>sp.GetRequiredService<ExistingFfprobeDocumentaryMediaProbe>());services.AddSingleton<IDocumentaryProductionFailureNormalizer,DocumentaryProductionFailureNormalizer>();services.AddSingleton<IDocumentaryProductionDiagnosticsWriter,DocumentaryProductionDiagnosticsWriter>();services.AddSingleton<IDocumentaryVisualProviderRouter,DocumentaryVisualProviderRouter>();services.AddSingleton<IDocumentaryVisualFallbackPolicy,DocumentaryVisualFallbackPolicy>();services.AddSingleton<IDocumentaryImageInspector,DocumentaryImageInspector>();services.AddScoped<IDocumentaryProductionVisualAdapter,ExistingDocumentaryVisualProductionAdapter>();services.AddSingleton<IDocumentaryNarrationVoiceResolver,DocumentaryNarrationVoiceResolver>();services.AddSingleton<IDocumentaryNarrationAudioInspector,DocumentaryNarrationAudioInspector>();services.AddSingleton<IDocumentaryNarrationAudioNormalizer,ExistingDocumentaryNarrationAudioNormalizer>();services.AddScoped<IDocumentaryNarrationProviderBinding,AzureSpeechDocumentaryNarrationProviderBinding>();services.AddScoped<IDocumentaryProductionNarrationAdapter,ExistingAzureSpeechDocumentaryNarrationAdapter>();services.AddSingleton<IDocumentaryNarrationSynthesisResultMapper,DocumentaryNarrationSynthesisResultMapper>();services.AddSingleton<IDocumentarySubtitleInspector,DocumentarySubtitleInspector>();services.AddScoped<IDocumentarySubtitleProviderBinding,ExistingDocumentarySubtitleProviderBinding>();services.AddScoped<IDocumentaryProductionSubtitleAdapter,ExistingDocumentarySubtitleAdapter>();services.AddSingleton<IDocumentarySubtitleGenerationResultMapper,DocumentarySubtitleGenerationResultMapper>();services.TryAddScoped<IProcessRunner,ProcessRunner>();services.AddSingleton<FfmpegArgumentBuilder>();services.AddScoped<IDocumentarySceneDependencyResolver,DocumentarySceneDependencyResolver>();services.AddScoped<IDocumentarySceneCompositionProviderBinding,ExistingFFmpegDocumentarySceneProviderBinding>();services.AddScoped<IDocumentarySceneVideoInspector,DocumentarySceneVideoInspector>();services.AddScoped<IDocumentaryProductionSceneCompositionAdapter,ExistingDocumentarySceneCompositionAdapter>();services.AddSingleton<IDocumentarySceneCompositionResultMapper,DocumentarySceneCompositionResultMapper>();services.AddScoped<IDocumentaryVariantDependencyResolver,DocumentaryVariantDependencyResolver>();services.AddSingleton<IDocumentaryVariantCompatibilityValidator,DocumentaryVariantCompatibilityValidator>();services.AddScoped<IDocumentaryVariantCompositionProviderBinding,ExistingFFmpegDocumentaryVariantProviderBinding>();services.AddScoped<IDocumentaryVariantVideoInspector,DocumentaryVariantVideoInspector>();services.AddScoped<IDocumentaryProductionVariantCompositionAdapter,ExistingDocumentaryVariantCompositionAdapter>();services.AddSingleton<IDocumentaryVariantCompositionResultMapper,DocumentaryVariantCompositionResultMapper>();services.AddSingleton<IDocumentaryMediaVerificationPolicyResolver,DocumentaryMediaVerificationPolicyResolver>();services.AddSingleton<IDocumentaryMediaVerificationEvaluator,DocumentaryMediaVerificationEvaluator>();services.AddScoped<IDocumentaryMediaVerificationProviderBinding,ExistingFFprobeDocumentaryMediaVerificationProviderBinding>();services.AddScoped<IDocumentaryProductionMediaVerificationAdapter,DocumentaryProductionMediaVerificationAdapter>();services.AddSingleton<IDocumentaryMediaVerificationResultMapper,DocumentaryMediaVerificationResultMapper>();services.AddScoped<IDocumentaryProductionAdapterRegistry,DocumentaryProductionAdapterRegistry>();services.AddSingleton<IDocumentaryVisualGenerationResultMapper,DocumentaryVisualGenerationResultMapper>();services.AddSingleton<IDocumentaryProductionExecutionRecordMapper,DocumentaryProductionExecutionRecordMapper>();services.AddScoped<IDocumentaryProductionExecutionContextFactory,DocumentaryProductionExecutionContextFactory>();services.AddScoped<IDocumentaryProductionWorkspaceManager,DocumentaryProductionWorkspaceManager>();services.AddScoped<IDocumentaryPhysicalArtifactRegistry,DocumentaryPhysicalArtifactRegistry>();services.AddScoped<IDocumentaryPhysicalArtifactInspector,DocumentaryPhysicalArtifactInspector>();services.AddSingleton<IDocumentaryProductionAttemptContextFactory,DocumentaryProductionAttemptContextFactory>();services.AddScoped<IDocumentaryProductionOperationRunner,DocumentaryProductionOperationRunner>();services.AddScoped<IDocumentaryProductionExecutionDependencyResolver,DocumentaryProductionExecutionDependencyResolver>();services.AddScoped<IDocumentaryProductionExecutionRequestBuilder,DocumentaryProductionExecutionRequestBuilder>();services.AddScoped<IDocumentaryProductionExecutionCoordinator,DocumentaryProductionExecutionCoordinator>();services.AddScoped<IDocumentaryProductionExecutionHost,DocumentaryProductionExecutionHost>();return services;}}
